     * a claim that names one without being a correction. */
    private void refuseBadCorrection(String sheetId, Long personId, Long claimId, BigDecimal amount,
            String corrects) {
        if (amount.signum() >= 0) {
            if (corrects != null) throw new ClaimCorrectionException();
            return;
        }
        if (corrects == null) throw new ClaimCorrectionException();
